func (this *Bit2me) ParseMarket(market any) map[string]any {
	var id *string = this.SafeString(market, "symbol", "")
	var parts []string = strings.Split(*id, "/")
	var baseId *string = this.SafeString(parts, 0)
	var quoteId *string = this.SafeString(parts, 1)
	var base *string = this.SafeCurrencyCode(baseId)
	var quote *string = this.SafeCurrencyCode(quoteId)
	var status *string = this.SafeString(market, "marketEnabled")
	var tradingFees any = this.SafeValue(this.Fees, "trading")
	var literal43341 map[string]any = map[string]any{
		"id":             id,
		"symbol":         nil,
		"base":           base,
		"quote":          quote,
		"settle":         nil,
		"baseId":         baseId,
		"quoteId":        quoteId,
		"settleId":       nil,
		"type":           "spot",
		"spot":           true,
		"margin":         false,
		"swap":           false,
		"future":         false,
		"option":         false,
		"active":         (status != nil && *status == "enabled"),
		"contract":       false,
		"linear":         nil,
		"inverse":        nil,
		"contractSize":   nil,
		"expiry":         nil,
		"expiryDatetime": nil,
		"strike":         nil,
		"optionType":     nil,
		"taker":          this.SafeNumber(tradingFees, "taker"),
		"maker":          this.SafeNumber(tradingFees, "maker"),
		"precision": map[string]any{
			"amount": this.ParseNumber(this.ParsePrecision(this.SafeString(market, "amountPrecision"))),
			"price":  this.ParseNumber(this.ParsePrecision(this.SafeString(market, "pricePrecision"))),
			"cost":   nil,
		},
		"limits": map[string]any{
			"leverage": map[string]any{
				"min": nil,
				"max": nil,
			},
			"amount": map[string]any{
				"min": this.SafeNumber(market, "minAmount"),
				"max": this.SafeNumber(market, "maxAmount"),
			},
			"price": map[string]any{
				"min": this.SafeNumber(market, "minPrice"),
				"max": this.SafeNumber(market, "maxPrice"),
			},
			"cost": map[string]any{
				"min": this.SafeNumber(market, "minOrderSize"),
				"max": nil,
			},
		},
		"created": this.Parse8601(this.SafeString(market, "marketEnabledAt")),
		"info":    market,
	}
	if base != nil && quote != nil {
		literal43341["symbol"] = *base + "/" + *quote
	}
	return this.SafeMarketStructure(literal43341)
}

