func (this *Bit2me) fetchCurrenciesBody(ch chan AsyncResult[map[string]any], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	includeTestnet, query := this.HandleOptionBoolAndParams(params, "fetchCurrencies", "includeTestnet", false)
	var ternaryStr49930 string = "false"
	if includeTestnet {
		ternaryStr49930 = "true"
	}
	var request map[string]any = map[string]any{
		"includeTestnet": ternaryStr49930,
	}
	var promises []any = []any{this.PublicGetV2CurrencyAssets(this.Extend(request, query)), this.PublicGetV1WalletSettingsAssets(query)}

	r := <-promiseAll(promises)
	if r.Err != nil {
		panic(r.Err)
	}
	var responses []any = r.Value
	//
	// assets
	//
	//     {
	//         "BTC": {
	//             "symbol": "BTC",
	//             "name": "Bitcoin",
	//             "slug": "bitcoin",
	//             "mainwebUri": "bitcoin",
	//             "uriScheme": "bitcoin",
	//             "hexColor": "#eca24d",
	//             "assetType": "currency",
	//             "addressRegex": "^([13][a-km-zA-HJ-NP-Z1-9]{25,34})|...",
	//             "hasImage": true,
	//             "hasPaymentRequest": true,
	//             "isERC20Token": false,
	//             "image": "/crypto-icons/v8/svg/btc-circle-solid-default.svg",
	//             "network": "BITCOIN",
	//             "enabled": true,
	//             "lite": false,
	//             "pairsWith": [ "EUR" ],
	//             "ticker": true,
	//             "loanable": true,
	//             "exponent": 8, // optional
	//             "createdAt": "2024-10-08", // optional
	//             "removedAt": "2025-05-22T00:00:00.000Z" // optional, set for delisted assets
	//         }
	//     }
	//
	// wallet settings
	//
	//     [
	//         {
	//             "symbol": "BTC",
	//             "actions": [ "deposit", "deposit-app", "deposit-web", "earn", "instant", "purchase", "transfer", "withdrawal" ]
	//         }
	//     ]
	//
	var assets map[string]any
	if 0 < len(responses) {
		assets, _ = responses[0].(map[string]any)
	}
	var settings []any
	if 1 < len(responses) {
		settings, _ = responses[1].([]any)
	}
	var settingsById map[string]any = this.IndexBy(settings, "symbol")
	var ids []string = nil
	if assets != nil {
		ids = make([]string, 0, len(assets))
		for objectKey := range assets {
			ids = append(ids, objectKey)
		}
	}
	var result map[string]any = map[string]any{}
	for i := 0; i < len(ids); i++ {
		var id string = ids[i]
		var asset map[string]any = this.SafeDictMap(assets, id, map[string]any{})
		var assetSettings, _ = settingsById[id].(map[string]any)
		// an operation that is not listed for an asset is not available for it
		var actions []any = this.SafeListSlice(assetSettings, "actions", []any{})
		var currency map[string]any = this.ParseCurrency(this.Extend(asset, map[string]any{
			"actions": actions,
		}))
		var code *string = SafeStringPtr(currency["code"])
		if code != nil {
			result[*code] = currency
		}
	}

	ch <- AsyncResult[map[string]any]{Value: result}
	return nil
}
func (this *Bit2me) ParseCurrency(rawCurrency any) map[string]any {
	var id *string = this.SafeString(rawCurrency, "symbol")
	var code *string = this.SafeCurrencyCode(id)
	var assetType *string = this.SafeString(rawCurrency, "assetType")
	var enabled *bool = this.SafeBool(rawCurrency, "enabled", false)
	var removedAt *string = this.SafeString(rawCurrency, "removedAt")
	var active bool = (enabled != nil && *enabled) && (removedAt == nil)
	var actions []any = this.SafeListSlice(rawCurrency, "actions", []any{})
	var deposit bool = this.InArray("deposit", actions)
	var withdraw bool = this.InArray("withdrawal", actions)
	// the exponent is only published for a handful of assets, fall back to the usual decimals
	var defaultExponent string
	if assetType != nil && *assetType == "fiat" {
		defaultExponent = "2"
	} else {
		defaultExponent = "8"
	}
	var precision *float64 = this.ParseNumber(this.ParsePrecision(this.SafeString(rawCurrency, "exponent", defaultExponent)))
	var networks map[string]any = map[string]any{}
	var networkId *string = this.SafeString(rawCurrency, "network")
	var networkCode *string = this.NetworkIdToCode(networkId, code)
	if networkCode != nil {
		networks[*networkCode] = map[string]any{
			"info":      rawCurrency,
			"id":        networkId,
			"network":   networkCode,
			"active":    active,
			"deposit":   deposit,
			"withdraw":  withdraw,
			"fee":       nil,
			"precision": precision,
			"limits": map[string]any{
				"withdraw": map[string]any{
					"min": nil,
					"max": nil,
				},
				"deposit": map[string]any{
					"min": nil,
					"max": nil,
				},
			},
		}
	}
	var ternaryStr61120 string = "crypto"
	if assetType != nil && *assetType == "fiat" {
		ternaryStr61120 = "fiat"
	}
	return this.SafeCurrencyStructure(map[string]any{
		"info":      rawCurrency,
		"id":        id,
		"code":      code,
		"name":      this.SafeString(rawCurrency, "name"),
		"active":    active,
		"deposit":   deposit,
		"withdraw":  withdraw,
		"networks":  networks,
		"fee":       nil,
		"precision": precision,
		"type":      ternaryStr61120,
		"limits": map[string]any{
			"amount": map[string]any{
				"min": nil,
				"max": nil,
			},
			"deposit": map[string]any{
				"min": nil,
				"max": nil,
			},
			"withdraw": map[string]any{
				"min": nil,
				"max": nil,
			},
		},
	})
}

