func (this *Bit2me) ParseTicker(ticker any, optionalArgs ...any) Ticker {
	//
	//     {
	//         "timestamp": 1793711134437,
	//         "symbol": "BTC/EUR",
	//         "open": 69219.9,
	//         "close": 69085.4,
	//         "bid": 69085.4,
	//         "ask": 69085.5,
	//         "percentage": -0.19,
	//         "high": 69613.8,
	//         "low": 68111,
	//         "baseVolume": 658.2554895,
	//         "quoteVolume": 45221164.74541575
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var marketId *string = this.SafeString(ticker, "symbol")
	var symbol *string = this.SafeSymbol(marketId, market)
	var timestamp *int64 = this.SafeInteger(ticker, "timestamp")
	var last *string = this.SafeString(ticker, "close")
	return this.SafeTicker(map[string]any{
		"symbol":        symbol,
		"timestamp":     timestamp,
		"datetime":      this.Iso8601(timestamp),
		"high":          this.SafeString(ticker, "high"),
		"low":           this.SafeString(ticker, "low"),
		"bid":           this.SafeString(ticker, "bid"),
		"bidVolume":     nil,
		"ask":           this.SafeString(ticker, "ask"),
		"askVolume":     nil,
		"vwap":          nil,
		"open":          this.SafeString(ticker, "open"),
		"close":         last,
		"last":          last,
		"previousClose": nil,
		"change":        nil,
		"percentage":    this.SafeString(ticker, "percentage"),
		"average":       nil,
		"baseVolume":    this.SafeString(ticker, "baseVolume"),
		"quoteVolume":   this.SafeString(ticker, "quoteVolume"),
		"info":          ticker,
	}, market)
}

