/**
 * @method
 * @name bit2me#fetchTrades
 * @description get the list of most recent trades for a particular symbol
 * @see https://api.bit2me.com/docs/pro/api-reference/marketdata/v1/trading/trade/last/get
 * @param {string} symbol unified symbol of the market to fetch trades for
 * @param {int} [since] timestamp in ms of the earliest trade to fetch
 * @param {int} [limit] the maximum amount of trades to fetch, default 50, max 50
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {Trade[]} a list of [trade structures](https://docs.ccxt.com/#/?id=public-trades)
 */
func (this *Bit2me) FetchTradesAsync(symbol string, optionalArgs ...any) <-chan AsyncResult[[]Trade] {
	ch := make(chan AsyncResult[[]Trade], 1)
	go this.fetchTradesBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Bit2me) fetchTradesBody(ch chan AsyncResult[[]Trade], symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var since *int64 = GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 2, map[string]any{})
	_ = params

	r := <-this.LoadMarketsAsync()
	if r.Err != nil {
		panic(r.Err)
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"symbol": market["id"],
	}
	if limit != nil {
		request["limit"] = min(*limit, 50)
	}

	responseRecv := <-this.PublicGetV1TradingTradeLast(this.Extend(request, params))
	if responseRecv.Err != nil {
		panic(responseRecv.Err)
	}
	var response []any = responseRecv.Value
	//
	//     [
	//         [ "sell", 69085.4, 0.00284291, 1793711134413 ],
	//         [ "buy", 69083.4, 0.00060614, 1793711113677 ]
	//     ]
	//
	// the exchange returns the newest trades first, reverse them so that trades sharing a timestamp keep their execution order
	var reversed []any = []any{}
	var length int = len(response)
	for i := 0; i < length; i++ {
		reversed = append(reversed, GetValue(response, (length-1)-i))
	}

	ch <- AsyncResult[[]Trade]{Value: TradesFromList(this.ParseTrades(reversed, market, since, limit))}
	return nil
}
func (this *Bit2me) ParseTrade(trade any, optionalArgs ...any) Trade {
	//
	// fetchTrades (public)
	//
	//     [ "sell", 69085.4, 0.00284291, 1793711134413 ]
	//
	// fetchMyTrades, fetchOrderTrades (private)
	//
	//     {
	//         "amount": 0.24,
	//         "amountCurrency": "BTC",
	//         "clientOrderId": null,
	//         "cost": 15600.12,
	//         "costEuro": 15600.12,
	//         "createdAt": "2024-05-07T14:09:02.310Z",
	//         "feeAmount": 15.60012,
	//         "feeCurrency": "EUR",
	//         "feePercentage": 0.1,
	//         "feePercentageDiscount": 0, // fetchOrderTrades only
	//         "id": "4278a86a-53e7-4997-9102-01646ae8954a",
	//         "isMaker": true,
	//         "orderId": "536ee1dc-528a-419e-9c00-5e04c010658d",
	//         "orderType": "limit",
	//         "price": 65000.5,
	//         "priceCurrency": "EUR",
	//         "side": "buy",
	//         "spaceCenterLevelId": null, // fetchOrderTrades only
	//         "symbol": "BTC/EUR"
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	if IsArray(trade) {
		var publicSide *string = this.SafeStringLower(trade, 0)
		var publicPrice *string = this.SafeString(trade, 1)
		var publicAmount *string = this.SafeString(trade, 2)
		var publicTimestamp *int64 = this.SafeInteger(trade, 3)
		var resolvedMarket map[string]any = this.SafeMarket(nil, market)
		return this.SafeTrade(map[string]any{
			"info":         trade,
			"id":           nil,
			"symbol":       resolvedMarket["symbol"],
			"timestamp":    publicTimestamp,
			"datetime":     this.Iso8601(publicTimestamp),
			"order":        nil,
			"type":         nil,
			"side":         publicSide,
			"takerOrMaker": nil,
			"price":        publicPrice,
			"amount":       publicAmount,
			"cost":         nil,
			"fee":          nil,
		}, resolvedMarket)
	}
	var marketId *string = this.SafeString(trade, "symbol")
	var privateMarket map[string]any = this.SafeMarket(marketId, market)
	var timestamp *int64 = this.Parse8601(this.SafeString(trade, "createdAt"))
	var isMaker *bool = this.SafeBool(trade, "isMaker")
	var takerOrMaker *string = nil
	if isMaker != nil {
		var takerOrMakerStr string
		if isMaker != nil && *isMaker {
			takerOrMakerStr = "maker"
		} else {
			takerOrMakerStr = "taker"
		}
		takerOrMaker = &takerOrMakerStr
	}
	var fee map[string]any = nil
	var feeCost *string = this.SafeString(trade, "feeAmount")
	if feeCost != nil {
		var feeRate *string = nil
		var feePercentage *string = this.SafeString(trade, "feePercentage")
		if feePercentage != nil {
			feeRate = Precise.StringDiv(feePercentage, "100")
		}
		fee = map[string]any{
			"cost":     feeCost,
			"currency": this.SafeCurrencyCode(this.SafeString(trade, "feeCurrency")),
			"rate":     feeRate,
		}
	}
	return this.SafeTrade(map[string]any{
		"info":         trade,
		"id":           this.SafeString(trade, "id"),
		"symbol":       privateMarket["symbol"],
		"timestamp":    timestamp,
		"datetime":     this.Iso8601(timestamp),
		"order":        this.SafeString(trade, "orderId"),
		"type":         this.ParseOrderType(this.SafeString(trade, "orderType")),
		"side":         this.SafeStringLower(trade, "side"),
		"takerOrMaker": takerOrMaker,
		"price":        this.SafeString(trade, "price"),
		"amount":       this.SafeString(trade, "amount"),
		"cost":         this.SafeString(trade, "cost"),
		"fee":          fee,
	}, privateMarket)
}

/**
 * @method
 * @name bit2me#fetchOHLCV
 * @description fetches historical candlestick data containing the open, high, low, and close price, and the volume of a market
 * @see https://api.bit2me.com/docs/pro/api-reference/marketdata/v1/trading/candle/get
 * @param {string} symbol unified symbol of the market to fetch OHLCV data for
 * @param {string} timeframe the length of time each candle represents
 * @param {int} [since] timestamp in ms of the earliest candle to fetch
 * @param {int} [limit] the maximum amount of candles to fetch, default 1000, max 1000
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {int} [params.until] timestamp in ms of the latest candle to fetch
 * @param {boolean} [params.paginate] default false, when true will automatically paginate by calling this endpoint multiple times. See in the docs all the [available parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
 * @returns {int[][]} A list of candles ordered as timestamp, open, high, low, close, volume
 */
func (this *Bit2me) FetchOHLCVAsync(symbol string, optionalArgs ...any) <-chan AsyncResult[[]OHLCV] {
	ch := make(chan AsyncResult[[]OHLCV], 1)
	go this.fetchOHLCVBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Bit2me) fetchOHLCVBody(ch chan AsyncResult[[]OHLCV], symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var timeframe string = GetArgString(optionalArgs, 0, "1m")
	_ = timeframe
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params

	r := <-this.LoadMarketsAsync()
	if r.Err != nil {
		panic(r.Err)
	}
	var market map[string]any = this.Market(symbol)
	paginate, paramsPaginate := this.HandleOptionBoolAndParams(params, "fetchOHLCV", "paginate", false)
	var maxLimit int = 1000
	if paginate {

		r1 := <-this.FetchPaginatedCallDeterministicAsync("fetchOHLCV", symbol, since, limit, timeframe, paramsPaginate, maxLimit)
		if r1.Err != nil {
			panic(r1.Err)
		}
		var retRes91919 []any = r1.Value
		if retRes91919 == nil {
			ch <- AsyncResult[[]OHLCV]{Value: nil}
		} else {
			ch <- AsyncResult[[]OHLCV]{Value: OHLCVsFromList(retRes91919)}
		}
		return nil
	}
	var requestLimit int64
	if limit == nil {
		requestLimit = int64(maxLimit)
	} else {
		requestLimit = min(*limit, int64(maxLimit))
	}
	var untilPtr *int64 = nil
	untilPtr, paramsUntil := this.HandleParamInteger(paramsPaginate, "until")
	until := func() any {
		if untilPtr != nil {
			return *untilPtr
		}
		return nil
	}()
	var request map[string]any = map[string]any{
		"symbol":   market["id"],
		"interval": this.SafeString(this.Timeframes, timeframe, timeframe),
		"limit":    requestLimit,
	}
	if since != nil {
		request["startTime"] = *since
	} else {
		// the endpoint returns the oldest candles first, so request a window that covers `limit` candles
		var duration int64 = this.ParseTimeframe(timeframe) * 1000
		var end any = this.Milliseconds()
		if until != nil {
			end = until
		}
		request["startTime"] = Subtract(end, requestLimit*duration)
	}
	if until != nil {
		request["endTime"] = until
	}

	responseRecv := <-this.PublicGetV1TradingCandle(this.Extend(request, paramsUntil))
	if responseRecv.Err != nil {
		panic(responseRecv.Err)
	}
	var response []any = responseRecv.Value

	//
	//     [
	//         [ 1793628000000, 69397.5, 69549.9, 69200.1, 69334.1, 20.37762874 ],
	//         [ 1793631600000, 69334, 69613.8, 68923.4, 69137.8, 22.29039127 ]
	//     ]
	//
	ch <- AsyncResult[[]OHLCV]{Value: OHLCVsFromList(this.ParseOHLCVs(response, market, timeframe, since, limit))}
	return nil
}
func (this *Bit2me) ParseOHLCV(ohlcv any, optionalArgs ...any) OHLCV {
	//
	//     [ 1793628000000, 69397.5, 69549.9, 69200.1, 69334.1, 20.37762874 ]
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	return OHLCVFromList([]any{this.SafeInteger(ohlcv, 0), this.SafeNumber(ohlcv, 1), this.SafeNumber(ohlcv, 2), this.SafeNumber(ohlcv, 3), this.SafeNumber(ohlcv, 4), this.SafeNumber(ohlcv, 5)})
}

