func (this *Bit2me) fetchTransfersBody(ch chan AsyncResult[[]TransferEntry], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var code *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = code
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params

	r := <-this.LoadMarketsAsync()
	if r.Err != nil {
		panic(r.Err)
	}
	var currency map[string]any = nil
	var request map[string]any = map[string]any{}
	if code != nil {
		currency = this.Currency(code)
		request["currency"] = currency["id"]
	}
	if since != nil {
		request["from"] = this.Iso8601(since)
	}
	if limit != nil {
		request["limit"] = min(*limit, 100)
	}
	until, query := this.HandleParamInteger(params, "until")
	if until != nil {
		request["to"] = this.Iso8601(until)
	}

	responseRecv := <-this.PrivateGetV1TradingMovement(this.Extend(request, query))
	if responseRecv.Err != nil {
		panic(responseRecv.Err)
	}
	var response []any = responseRecv.Value

	//
	//     [
	//         {
	//             "amount": 100,
	//             "createdAt": "2025-03-10T09:30:00.000Z",
	//             "currency": "EUR",
	//             "id": "1b2c3d4e-5f60-4718-9a2b-3c4d5e6f7a8b",
	//             "movementType": "deposit",
	//             "serviceOrderName": "wallet",
	//             "status": "completed",
	//             "walletId": "3a9f1c2d-7e4b-4f6a-8c1d-2b3e4f5a6b7c"
	//         }
	//     ]
	//
	ch <- AsyncResult[[]TransferEntry]{Value: TransferEntriesFromList(this.ParseTransfers(response, currency, since, limit))}
	return nil
}
func (this *Bit2me) ParseTransfer(transfer any, optionalArgs ...any) TransferEntry {
	//
	// transfer
	//
	//     {
	//         "balance": 1350.5,
	//         "blockedBalance": 0,
	//         "createdAt": "2023-09-13T14:05:42.149Z",
	//         "currency": "EUR",
	//         "id": "3a9f1c2d-7e4b-4f6a-8c1d-2b3e4f5a6b7c",
	//         "rawBalance": "1350.5",
	//         "rawBlockedBalance": "0",
	//         "userId": "2bf436fc-43e6-459a-b647-6b446f72ad96"
	//     }
	//
	// fetchTransfers
	//
	//     {
	//         "amount": 100,
	//         "createdAt": "2025-03-10T09:30:00.000Z",
	//         "currency": "EUR",
	//         "id": "1b2c3d4e-5f60-4718-9a2b-3c4d5e6f7a8b",
	//         "movementType": "deposit",
	//         "serviceOrderName": "wallet",
	//         "status": "completed",
	//         "walletId": "3a9f1c2d-7e4b-4f6a-8c1d-2b3e4f5a6b7c"
	//     }
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var currencyId *string = this.SafeString(transfer, "currency")
	var movementType *string = this.SafeString(transfer, "movementType")
	var accountsById, _ = this.Options["accountsById"].(map[string]any)
	var fromAccount any = nil
	var toAccount any = nil
	var id *string = nil
	var timestamp *int64 = nil
	var status *string = nil
	if movementType != nil {
		// a movement from the historical list
		id = this.SafeString(transfer, "id")
		timestamp = this.Parse8601(this.SafeString(transfer, "createdAt"))
		status = this.ParseTransferStatus(this.SafeString(transfer, "status"))
		var wallet *string = this.SafeString(accountsById, "wallet")
		var trading *string = this.SafeString(accountsById, "trading")
		if movementType != nil && *movementType == "deposit" {
			fromAccount = wallet
		} else {
			fromAccount = trading
		}
		if movementType != nil && *movementType == "deposit" {
			toAccount = trading
		} else {
			toAccount = wallet
		}
	} else {
		// the trading wallet returned by deposit/withdraw, createdAt is the wallet creation date
		statusStr := "ok"
		status = &statusStr
	}
	var literal180815 map[string]any = map[string]any{
		"info":        transfer,
		"id":          nil,
		"timestamp":   timestamp,
		"datetime":    this.Iso8601(timestamp),
		"currency":    this.SafeCurrencyCode(currencyId, currency),
		"amount":      this.SafeNumber(transfer, "amount"),
		"fromAccount": fromAccount,
		"toAccount":   toAccount,
		"status":      nil,
	}
	if id != nil {
		literal180815["id"] = *id
	}
	if status != nil {
		literal180815["status"] = *status
	}
	return TransferEntryFromMap(literal180815)
}
func (this *Bit2me) ParseTransferStatus(status *string) *string {
	var statuses map[string]any = map[string]any{
		"completed": "ok",
		"pending":   "pending",
		"failed":    "failed",
		"cancelled": "canceled",
	}
	return this.SafeString(statuses, status, status)
}
func (this *Bit2me) Nonce() int64 {
	// the nonce must be a unix timestamp in milliseconds, within 5 seconds of the server clock
	return this.Milliseconds()
}
func (this *Bit2me) Sign(path string, optionalArgs ...any) map[string]any {
	var api []string = GetArgStringSlice(optionalArgs, 0, []string{"public"})
	_ = api
	var method string = GetArgString(optionalArgs, 1, "GET")
	_ = method
	params := GetArg(optionalArgs, 2, map[string]any{})
	_ = params
	var apiName string = api[0]
	var requestHeaders map[string]any = nil
	var requestBody *string = nil
	var query any = this.Omit(params, this.ExtractParams(path))
	var url string = "/" + this.ImplodeParams(path, params)
	var isGetOrDelete bool = (method == "GET") || (method == "DELETE")
	if isGetOrDelete {
		if queryMap, _ := query.(map[string]any); len(queryMap) > 0 {
			url += "?" + this.Urlencode(query)
		}
	}
	if apiName == "private" {
		this.CheckRequiredCredentials()
		// https://api.bit2me.com/docs/guides/authentication
		// message = nonce:path[:compactJsonBody] -> sha256 (binary) -> hmac-sha512 (base64)
		var nonce string = strconv.FormatInt(this.Nonce(), 10)
		var message string = nonce + ":" + url
		if !isGetOrDelete {
			// always send a json body, some http clients label an empty body as octet-stream and the gateway rejects it
			// an empty query is spelled out, php encodes an empty array as [] and would sign and post that instead of {}
			if queryMap, _ := query.(map[string]any); len(queryMap) > 0 {
				jsonText := this.Json(query)
				requestBody = &jsonText
			} else {
				requestBodyStr := "{}"
				requestBody = &requestBodyStr
			}
			message += ":" + *requestBody
		}
		var digest any = this.Hash(this.Encode(message), sha256, "binary")
		var signature string = this.Hmac(digest, this.Encode(this.Secret), sha512, "base64")
		requestHeaders = map[string]any{
			"x-api-key":     this.ApiKey,
			"x-nonce":       nonce,
			"api-signature": signature,
		}
		if requestBody != nil {
			if requestHeaders != nil {
				requestHeaders["Content-Type"] = "application/json"
			}
		}
	}
	var apiUrl *string = this.SafeString(this.Urls["api"], apiName)
	if apiUrl == nil {
		panic(NotSupported(this.Id + " does not have a URL for " + apiName + " endpoints"))
	}
	var fullUrl string = *apiUrl + url
	return map[string]any{
		"url":     fullUrl,
		"method":  method,
		"body":    requestBody,
		"headers": requestHeaders,
	}
}
func (this *Bit2me) HandleErrors(httpCode int64, reason string, url string, method string, headers any, body string, response any, requestHeaders any, requestBody any) any {
	if response == nil {
		return nil // fallback to default error handler
	}
	//
	//     {"statusCode":404,"error":"Not Found","message":"Market not found for symbol FOO/BAR","reqId":"9834b8a8-97b8-470d-ade2-3d31687c0723"}
	//     {"code":403,"description":"invalid credentials"}
	//     {"message":"Validation errors","errors":[{"code":"INVALID_REQUEST_PARAMETER","message":"Invalid parameter (symbol): Value is required but was not provided","in":"query","name":"symbol"}]}
	//     {"message":["type must be one of the following values: all, fiat, crypto"],"error":"Bad Request","statusCode":400}
	//     {"statusCode":412,"error":"Precondition Failed","message":"...","errorPayload":{"code":"ORDER_AMOUNT_LOWER_MARKET_MIN"}}
	//
	var errorCode *string = this.SafeString2(response, "code", "statusCode")
	var errorsList []any = SafeListTyped(response, "errors")
	var errorPayload map[string]any = SafeMapTyped(response, "errorPayload")
	var payloadCode *string = this.SafeString(errorPayload, "code")
	if (errorCode != nil) || (errorsList != nil) || (payloadCode != nil) {
		var message *string = this.SafeStringN(response, []any{"message", "description", "error"})
		var feedback string = this.Id + " " + body
		this.ThrowExactlyMatchedException(this.Exceptions["exact"], payloadCode, feedback)
		this.ThrowBroadlyMatchedException(this.Exceptions["broad"], message, feedback)
		this.ThrowBroadlyMatchedException(this.Exceptions["broad"], body, feedback)
		this.ThrowExactlyMatchedException(this.Exceptions["exact"], errorCode, feedback)
		panic(ExchangeError(feedback))
	}
	return nil
}

func NewBit2me(userConfig map[string]any) *Bit2me {
	p := newBit2me()
	p.Init(userConfig)
	return p
}

func (this *Bit2me) Init(userConfig map[string]any) {
	this.Exchange = Exchange{}
	this.Exchange.DerivedExchange = this
	this.Exchange.InitParent(userConfig, this.Describe(), this)
}

